BEGIN;
SELECT plan(23);
INSERT INTO households(id,name)VALUES('e3000000-0000-4000-8000-000000000001','synthetic medical A'),('e3000000-0000-4000-8000-000000000002','synthetic medical B');
INSERT INTO auth.users(id,email)VALUES('e3000000-0000-4000-8000-000000000003','medical-a@example.invalid'),('e3000000-0000-4000-8000-000000000004','medical-b@example.invalid');
UPDATE profiles SET household_id='e3000000-0000-4000-8000-000000000001',is_approved=true,role='owner' WHERE id='e3000000-0000-4000-8000-000000000003';
UPDATE profiles SET household_id='e3000000-0000-4000-8000-000000000002',is_approved=true WHERE id='e3000000-0000-4000-8000-000000000004';
INSERT INTO children(id,household_id,name)VALUES('e3000000-0000-4000-8000-000000000005','e3000000-0000-4000-8000-000000000001','synthetic medical sibling');
CREATE TEMP TABLE med_input(value jsonb);GRANT ALL ON med_input TO authenticated;
INSERT INTO med_input VALUES(jsonb_build_object('kind','vaccination','title','synthetic vaccine','dose',1,'status','planned','scheduled_date',current_date+3,'completed_date',NULL,'memo','synthetic private memo','remind',true,'source_key','jihs-2026-10-01'));
CREATE TEMP TABLE med_result(value jsonb);GRANT ALL ON med_result TO authenticated;
CREATE TEMP TABLE med_share(value jsonb);GRANT ALL ON med_share TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"e3000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
INSERT INTO med_result SELECT save_medical_record('e3000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),NULL,(SELECT value FROM med_input));
SELECT is((SELECT value->>'status' FROM med_result),'saved','planned vaccination saved');
SELECT is((SELECT count(*) FROM calendar_events WHERE medical_record_id='e3000000-0000-4000-8000-000000000006'),1::bigint,'same transaction creates one linked calendar event');
SELECT is((SELECT count(*) FROM event_reminders WHERE event_uid='e3000000-0000-4000-8000-000000000006'),1::bigint,'existing reminder pipeline configured');
SELECT is((save_medical_record('e3000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),NULL,(SELECT value FROM med_input))->>'status'),'replayed','same creation replay does not duplicate reminders');
SELECT is((SELECT count(*) FROM event_reminders),1::bigint,'replay leaves one reminder');
SELECT throws_ok($$DELETE FROM event_reminders WHERE event_uid='e3000000-0000-4000-8000-000000000006'$$,'42501',NULL,'linked reminder cannot drift from medical record');
SELECT throws_ok($$UPDATE event_reminders SET remind_kind='minutes',remind_minutes_before=30 WHERE event_uid='e3000000-0000-4000-8000-000000000006'$$,'42501',NULL,'linked reminder cannot be independently rescheduled');

INSERT INTO calendar_events(id,household_id,title,is_all_day,start_date,end_date,source,created_by)VALUES('e3000000-0000-4000-8000-000000000009','e3000000-0000-4000-8000-000000000001','synthetic ordinary event',true,current_date+3,current_date+3,'native','e3000000-0000-4000-8000-000000000003');
SELECT throws_ok($$UPDATE event_reminders SET event_uid='e3000000-0000-4000-8000-000000000009' WHERE event_uid='e3000000-0000-4000-8000-000000000006'$$,'42501',NULL,'linked reminder cannot escape by moving to an ordinary event');
SELECT throws_ok($$UPDATE medical_records SET title='bypass'$$,'42501',NULL,'no direct update grant');
SELECT throws_ok($$DELETE FROM medical_records$$,'42501',NULL,'history cannot be deleted directly');
SELECT throws_ok($$UPDATE calendar_events SET title='bypass' WHERE medical_record_id IS NOT NULL$$,'42501',NULL,'linked calendar cannot drift from medical record');
SELECT throws_ok($$DELETE FROM calendar_events WHERE medical_record_id IS NOT NULL$$,'42501',NULL,'linked calendar cannot be deleted directly');
SELECT is((save_medical_record('e3000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),'2020-01-01T00:00:00Z',(SELECT value||'{"dose":2}' FROM med_input))->>'status'),'conflict','stale record edit is rejected');
UPDATE med_result SET value=save_medical_record('e3000000-0000-4000-8000-000000000006',(SELECT id FROM children WHERE is_legacy),(value->'record'->>'updated_at')::timestamptz,(SELECT value||jsonb_build_object('status','completed','completed_date',current_date) FROM med_input));
SELECT is((SELECT value->>'status' FROM med_result),'saved','completion saved with current version');
SELECT is((SELECT count(*) FROM event_reminders),0::bigint,'completion removes only its reminder');
SELECT is((SELECT title FROM calendar_events WHERE medical_record_id IS NOT NULL),'完了: synthetic vaccine','calendar retains completed history');
SELECT throws_ok($$SELECT save_medical_record('e3000000-0000-4000-8000-000000000006','e3000000-0000-4000-8000-000000000005',NULL,(SELECT value FROM med_input))$$,'42501',NULL,'existing record cannot be moved to a sibling');
SELECT throws_ok($$SELECT save_medical_record('e3000000-0000-4000-8000-000000000007',(SELECT id FROM children WHERE is_legacy),NULL,(SELECT value||'{"source_key":"unknown"}' FROM med_input))$$,'23514',NULL,'unverified source rejected');
INSERT INTO med_share SELECT create_child_share((SELECT id FROM children WHERE is_legacy),false,false,true,false,NULL);
SELECT set_config('request.jwt.claims','{"sub":"e3000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
SELECT is((SELECT count(*) FROM medical_records),0::bigint,'foreign household cannot read raw medical data');
SELECT throws_ok($$SELECT save_medical_record('e3000000-0000-4000-8000-000000000008','e3000000-0000-4000-8000-000000000005',NULL,(SELECT value FROM med_input))$$,'42501',NULL,'foreign household cannot create');
SELECT accept_child_share((SELECT value->>'token' FROM med_share));
SELECT is((SELECT jsonb_array_length(shared_child_snapshot((value->>'id')::uuid)->'medical') FROM med_share),1,'explicit health permission grants medical whitelist');
SELECT ok(NOT (SELECT shared_child_snapshot((value->>'id')::uuid)->'medical'->0 ? 'memo' FROM med_share),'medical free memo never leaks through shared whitelist');
RESET ROLE;
SELECT ok(NOT has_function_privilege('anon','public.save_medical_record(uuid,uuid,timestamptz,jsonb)','EXECUTE'),'anon has no RPC grant');
SELECT * FROM finish();ROLLBACK;
